from pymatgen.core import Structure, Composition
import pandas as pd
import numpy as np
import warnings
warnings.filterwarnings('ignore')

train = pd.read_csv('nlo_shg_train.csv')
pool = pd.read_csv('nlo_pool.csv')

def elems(f):
    return set(Composition(f.replace(' ','')).elements)

# All As-containing train
print("=== TRAIN As-containing ===")
for i,r in train.iterrows():
    c = Composition(r.formula.replace(' ',''))
    if 'As' in [str(e) for e in c.elements]:
        print(f"{r.formula:25s} {r.shg:8.2f}  {list(c.as_dict().keys())}")

print("\n=== TRAIN Te-containing (again with more) ===")
for i,r in train.iterrows():
    c = Composition(r.formula.replace(' ',''))
    if 'Te' in [str(e) for e in c.elements]:
        print(f"{r.formula:25s} {r.shg:8.2f}")

print("\n=== TRAIN with Ba ===")
for i,r in train.iterrows():
    c = Composition(r.formula.replace(' ',''))
    if 'Ba' in [str(e) for e in c.elements]:
        print(f"{r.formula:25s} {r.shg:8.2f}")

print("\n=== TRAIN with Ta or Nb ===")
for i,r in train.iterrows():
    c = Composition(r.formula.replace(' ',''))
    els = [str(e) for e in c.elements]
    if 'Ta' in els or 'Nb' in els:
        print(f"{r.formula:25s} {r.shg:8.2f}")

print("\n=== TRAIN with Hg ===")
for i,r in train.iterrows():
    c = Composition(r.formula.replace(' ',''))
    if 'Hg' in [str(e) for e in c.elements]:
        print(f"{r.formula:25s} {r.shg:8.2f}")

print("\n=== TRAIN P-containing high ===")
for i,r in train.iterrows():
    c = Composition(r.formula.replace(' ',''))
    if 'P' in [str(e) for e in c.elements] and r.shg > 20:
        print(f"{r.formula:25s} {r.shg:8.2f}")

print("\n=== TRAIN I-4 or I-42d ===")
from pymatgen.symmetry.analyzer import SpacegroupAnalyzer
for i,r in train.iterrows():
    s = Structure.from_str(r.poscar, fmt='poscar')
    try:
        sga = SpacegroupAnalyzer(s, symprec=0.1)
        sg = sga.get_space_group_symbol()
    except:
        continue
    if sg in ('I-4', 'I-42d', 'I-42m', 'P-42m', 'I-4m2'):
        print(f"{r.formula:25s} {r.shg:8.2f}  {sg}")
